function resetPlacements(){
  placements = {};
  for(let p=1;p<=4;p++) placements[p] = {settlements:new Set(), roads:new Set(), cities:new Set()};
  winner = null;
}

// --- 盤面生成 ------------------------------------------------------------
function shuffle(a){ for(let i=a.length-1;i>0;i--){ const j=Math.random()*(i+1)|0; [a[i],a[j]]=[a[j],a[i]]; } return a; }

// ヘクスの隣接（2頂点を共有するヘクス同士が隣り合っている）
const HEX_ADJ=(()=>{
  const share={};
  for(const k in GEO.vertex_hexes){ const hs=GEO.vertex_hexes[k];
    for(let i=0;i<hs.length;i++) for(let j=i+1;j<hs.length;j++){
      const a=Math.min(hs[i],hs[j]), b=Math.max(hs[i],hs[j]); const key=a+","+b;
      share[key]=(share[key]||0)+1;
    }
  }
  const adj={}; for(const h of GEO.hexes) adj[h.id]=[];
  for(const key in share){ if(share[key]===2){ const [a,b]=key.split(",").map(Number); adj[a].push(b); adj[b].push(a); } }
  return adj;
})();

// 数字配置が公式ルールに反しないか（6-8/同数字/2-12 が隣り合わない）
function numbersLegal(){
  for(const h of GEO.hexes){
    const n=board[h.id]?board[h.id].number:null; if(n==null) continue;
    for(const nb of HEX_ADJ[h.id]){
      const m=board[nb]?board[nb].number:null; if(m==null) continue;
      if(n===m) return false;                                   // 同じ数字が隣接
      if((n===6||n===8)&&(m===6||m===8)) return false;          // 赤数字(6,8)が隣接
      if((n===2||n===12)&&(m===2||m===12)) return false;        // 2/12が隣接（バランス盤面の慣例）
    }
  }
  return true;
}

function randomBoard(){
  // 資源の並びと数字の並びの両方を振り直しながら、公式の隣接ルールを満たす盤面を必ず作る。
  // 数字だけ入れ替えても解が無い資源配置があるため、外側で資源からやり直すのが要点。
  const resPool=[]; for(const [k,n] of Object.entries(RES_COUNTS)) for(let i=0;i<n;i++) resPool.push(k);
  for(let outer=0; outer<200; outer++){
    const res=shuffle(resPool.slice());
    board={};
    GEO.hexes.forEach((h,i)=>{ board[h.id]={resource:res[i], number:null}; });
    const numbered=GEO.hexes.filter(h=>board[h.id].resource!=="desert").map(h=>h.id);
    for(let attempt=0; attempt<200; attempt++){
      const nums=shuffle(TOKENS.slice());
      numbered.forEach((hid,i)=>{ board[hid].number=nums[i]; });
      if(numbersLegal()) return;   // 合法盤面が完成
    }
    // この資源配置では200回試しても無理 → 資源から振り直す
  }
  // ここに来ることは事実上ないが、来た場合でも最後の状態を返す（描画は壊れない）
}

// 公式の螺旋順（島の角から中央へ反時計回り）。geometry座標から算出済みの固定順。
const SPIRAL_ORDER=[7,3,0,1,2,6,11,15,18,17,16,12,8,4,5,10,14,13,9];
// 標準の数値トークン列 A〜R（アルファベット順）
const OFFICIAL_TOKENS=[5,2,6,3,8,10,9,12,11,4,8,10,9,4,5,6,3,11];
// 資源はそのままに、数字だけ公式の螺旋配置で置き直す（砂漠は飛ばす）
function assignOfficialNumbers(){
  let i=0;
  for(const hid of SPIRAL_ORDER){
    const b=board[hid];
    if(!b || b.resource==="desert"){ if(b) b.number=null; continue; }
    b.number=OFFICIAL_TOKENS[i++];
  }
}
// 公式配置の盤面を作る: 資源はランダム、数字は螺旋で公式どおり
function officialBoard(){
  const resPool=[]; for(const [k,n] of Object.entries(RES_COUNTS)) for(let i=0;i<n;i++) resPool.push(k);
  const res=shuffle(resPool.slice());
  board={};
  GEO.hexes.forEach((h,i)=>{ board[h.id]={resource:res[i], number:null}; });
  assignOfficialNumbers();
}

// --- 座標フィッティング --------------------------------------------------
let TF; // {s, ox, oy}
function computeTransform(target=560, pad=26){
  let minX=1e9,maxX=-1e9,minY=1e9,maxY=-1e9;
  for(const v of GEO.vertices){ minX=Math.min(minX,v.x); maxX=Math.max(maxX,v.x); minY=Math.min(minY,v.y); maxY=Math.max(maxY,v.y); }
  const s = target/(maxX-minX);
  TF = {s, ox: pad - minX*s, oy: pad - minY*s, w: target+pad*2, h:(maxY-minY)*s+pad*2};
}
const TX = x => x*TF.s + TF.ox;
const TY = y => y*TF.s + TF.oy;

function hexCornersPx(h){
  const pts=[];
  for(let i=0;i<6;i++){
    const a = Math.PI/180*(60*i-30);
    pts.push([TX(h.cx+Math.cos(a)), TY(h.cy+Math.sin(a))]);
  }
  return pts;
}

