const NS = "http://www.w3.org/2000/svg";
function el(tag,attrs){ const e=document.createElementNS(NS,tag); for(const k in attrs) e.setAttribute(k,attrs[k]); return e; }

function ownerOf(kind,id){ // kind: 'settlements'|'roads'
  for(let p=1;p<=numPlayers;p++) if(placements[p][kind].has(id)) return p;
  return null;
}

// --- 最善配置スコア -------------------------------------------------------
let showBest=false;
let SCORE_METHOD="strategy";   // scoreMethodセレクトの現在値（strategy/model/emp/expert/mcts）
// MCTS最善手表示（実戦アドバイス用・非同期・キャッシュ付き）
let mctsAdv={key:null, stats:null, computing:false};
function _mctsAdvKey(){
  // 現局面の署名（盤面+全員の配置+手番）が変わったら再計算
  const pl=[];
  for(let p=1;p<=numPlayers;p++){ const x=placements[p]; if(!x) continue;
    pl.push(p+":"+[...x.settlements].sort().join(",")+"/"+[...x.roads].sort().join(",")); }
  const activeP = sim ? sim.order[sim.step] : (typeof active!=="undefined"?active:1);
  return activeP+"|"+pl.join(";");
}
function triggerMCTSAdvice(){
  const key=_mctsAdvKey();
  if(mctsAdv.key===key || mctsAdv.computing) return;   // 既に計算済み/計算中
  // 対戦AIの手番中はアドバイス計算を起動しない（AI自身のMCTSと衝突し盤面が壊れるため）
  const activeP = sim ? sim.order[sim.step] : (typeof active!=="undefined"?active:1);
  if(game && game.ai && isAI(activeP)) return;
  if(MCTS_BUSY) return;   // 他のMCTSが実行中なら今回はスキップ（次のrenderで再試行される）
  mctsAdv.computing=true;
  mctsPlacementAsync(6, 8, ()=>{ if(showBest) render(); }).then(stats=>{
    mctsAdv={key, stats, computing:false};
    if(showBest) render();
  }).catch(()=>{ mctsAdv.computing=false; });
}
